def has_pair_sum(nums, target):
    i, j = 0, len(nums) - 1
    while i < j:
        current = nums[i] + nums[j]
        if current == target:
            return True
        elif current < target:
            i += 1
        else:
            j -= 1
    return False

def remove_duplicates_sorted(nums):
    if not nums:
        return 0
    write = 1
    for read in range(1, len(nums)):
        if nums[read] != nums[read - 1]:
            nums[write] = nums[read]
            write += 1
    return write

def bisect_left(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def int_sqrt(n):
    if n < 2:
        return n
    lo, hi = 1, n // 2
    ans = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def moving_average(values, k):
    if len(values) < k or k <= 0:
        return []
    window_sum = sum(values[:k])
    averages = [window_sum / k]
    for i in range(k, len(values)):
        window_sum += values[i] - values[i - k]
        averages.append(window_sum / k)
    return averages

def length_of_longest_substring(s):
    seen = {}
    start = 0
    max_len = 0
    for idx, ch in enumerate(s):
        if ch in seen and seen[ch] >= start:
            start = seen[ch] + 1
        seen[ch] = idx
        max_len = max(max_len, idx - start + 1)
    return max_len

def eval_rpn(tokens):
    stack = []
    for token in tokens:
        if token in {"+", "-", "*"}:
            b, a = stack.pop(), stack.pop()
            if token == "+": stack.append(a + b)
            elif token == "-": stack.append(a - b)
            elif token == "*": stack.append(a * b)
        else:
            stack.append(int(token))
    return stack[0]

def daily_temperatures(temps):
    ans = [0] * len(temps)
    stack = []
    for i, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            prev_i = stack.pop()
            ans[prev_i] = i - prev_i
        stack.append(i)
    return ans

def gcd(a, b):
    if b == 0:
        return abs(a)
    return gcd(b, a % b)

